import re
from auto_config.generator.gnb.managed_objects.managed_object import ManagedObject


class VlanifParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        vlan_id = execution_config['vlan_id']
        if self.is_mo_ecpri:
            ethif_id = int(re.search(r'ETHIF-(\d+)', self.dist_name).group(1))
            tnl_id = self.tnl_id
            if execution_config['is_fullrack']:
                vlan_id = (tnl_id - 1) * ethif_id
            else:
                vlan_id = ethif_id
                self.set_parameter('userLabel', f'eCPRI-{ethif_id}')
        self.set_parameter('vlanId', vlan_id)
